package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;
final class OperationOverview {
 static JSONObject read(MainActivity c)throws Exception{long now=System.currentTimeMillis();JSONArray cards=new JSONArray(),issues=new JSONArray();JSONArray web;try{web=new JSONArray(c.getSharedPreferences("loki_web_console",0).getString("outbox","[]"));}catch(Exception unreadable){web=new JSONArray();issues.put("conversation_records");}JSONArray selected=OperationStatusPolicy.conversationRows(web,12);for(int i=0;i<web.length();i++)if(web.optJSONObject(i)==null){issues.put("conversation_records");break;}for(int i=0;i<selected.length();i++){JSONObject row=selected.getJSONObject(i);cards.put(OperationStatusPolicy.card("conversation",row.optString("key"),"会話："+row.optString("message"),row.optBoolean("tracked")?row.optString("requestState"):"UNKNOWN",row.optLong("receiptAt",row.optLong("time")),now));}
 JSONObject workspace=ConversationWorkspace.snapshot(c);JSONObject progress=workspace.optJSONObject("conversation");if(progress!=null){JSONObject safe=ConversationDeliveryState.safe(progress);cards.put(OperationStatusPolicy.card("conversation",safe.optString("id"),ConversationDeliveryState.label(safe,workspace.optBoolean("connected")),workspace.optBoolean("connected")?safe.optString("phase"):"UNCONFIRMED",workspace.optLong("receivedAt"),now));}String latest=c.getSharedPreferences("workspace_control",0).getString("latest","");if(!latest.isEmpty())try{JSONObject request=ConversationWorkspace.command(c,latest);boolean same=latest.equals(workspace.optString("commandId"));String phase=same?workspace.optString("commandPhase"):request.optLong("expiresAt")<now?"UNCONFIRMED":"QUEUED";cards.put(OperationStatusPolicy.card("workspace",latest,request.optString("action").equals("calendar_edit")?"予約候補の訂正":"会話の参照先変更",phase,same?workspace.optLong("at"):request.optLong("expiresAt")-600000,now));}catch(Exception missing){cards.put(OperationStatusPolicy.card("workspace",latest,"端末操作","UNCONFIRMED",0,now));}
 JSONObject control;try{control=MeetingControl.status(c);}catch(Exception unreadable){control=new JSONObject().put("request",new JSONObject());issues.put("meeting_state");}JSONObject request=control.getJSONObject("request");if(!request.optString("requestId").isEmpty())cards.put(OperationStatusPolicy.card("meeting",request.optString("requestId"),"録音："+(request.optString("action").equals("start")?"録音セッション":request.optString("action").equals("stop")?"終了・保存":"スマホへの取り込み"),request.optString("phase","UNCONFIRMED"),request.optLong("updatedAt",request.optLong("expiresAt")-120000),now));
 JSONArray inbox;try{inbox=SecretaryInbox.list(c).getJSONArray("items");}catch(Exception unreadable){inbox=new JSONArray();issues.put("inbox_records");}for(int i=0;i<inbox.length()&&i<12;i++){JSONObject row=inbox.optJSONObject(i);if(row==null){issues.put("inbox_records");continue;}String stage=row.optString("displayStage");String phase=stage.equals("review_wait")?"AWAITING_CONFIRMATION":stage.equals("pending")?"DEFERRED":stage.equals("completed")?"COMPLETED":stage.equals("cancelled")?"CANCELLED":"UNCONFIRMED";cards.put(OperationStatusPolicy.card("inbox",row.optString("id"),"保留："+row.optString("title"),phase,row.optLong("updatedAt",row.optLong("createdAt")),now));}
 JSONObject runtime;try{runtime=c.webConversationRuntime();}catch(Exception unreadable){runtime=new JSONObject();issues.put("runtime_state");}return new JSONObject().put("at",now).put("cards",cards).put("issues",issues).put("runtime",runtime).put("transfers",workspace.optJSONArray("transfers")==null?new JSONArray():workspace.getJSONArray("transfers")).put("transferStateFresh",workspace.optBoolean("connected")).put("transferReceivedAt",workspace.optLong("receivedAt")).put("phoneHealth",LocalHealthCheck.publicSummary(LocalHealthCheck.snapshot(c))).put("glassHealth",workspace.optJSONObject("health")==null?new JSONObject():workspace.getJSONObject("health"));}
 private OperationOverview(){}
}